109	    // key in the final merged style object (Chakra assigns component style props after `__css`),
110	    // so this would read the literal "bay blue" instead — proven by an actual mutation run, not
111	    // assumed; see the PR body / step report for that run's before/after output.
112	    expect(getComputedStyle(swatch).backgroundColor).toBe('var(--zimm-color-bg-02)');
113	  });
114	});
