1	import React from 'react';
2	import type { Meta, StoryObj } from '@storybook/react-webpack5';
3	import { MemoryRouter } from 'react-router-dom';
4	import { expect, within } from 'storybook/test';
5	import { ZimmColourSwatch } from '.';
6	
7	/** Placeholder swatch fill — doesn't need to resolve to a real product, just a working image URL. */
8	const SAMPLE_IMAGE_URL = 'https://picsum.photos/seed/zimmermann-bay-blue/400/600';
9	
10	const meta: Meta<typeof ZimmColourSwatch> = {
11	  title: 'Commerce/ZimmColourSwatch',
12	  component: ZimmColourSwatch,
13	  argTypes: {
14	    name: { control: 'text' },
15	    imageUrl: { control: 'text' },
16	    href: { control: 'text' },
17	    isSelected: { control: 'boolean' },
18	    isFocusable: { control: 'boolean' },
19	  },
20	  decorators: [
