  /* AFTER: proposed fix — position:relative + z-index:1 scoped to :focus-visible only. */
  .row-after .swatch:focus-visible {
    position: relative;
    z-index: 1;
    outline: var(--zimm-focus-ring);
    outline-offset: var(--zimm-focus-ring-offset-default);
  }

  /* DIAGNOSTIC ONLY — not part of the proposed fix. Isolates whether z-index alone (with no
     position change, so the element stays position:static) is already enough to win the paint
     order, given the swatch is a direct flex item of `.row` (Flexbox spec: "z-index values other
     than auto create a stacking context even if position is static" — a flex-item-specific
     carve-out). Exists purely to verify the "position:relative is required for z-index to do
     anything" claim empirically for *this specific* flex-item context before reporting on it. */
  .row-zonly .swatch:focus-visible {
    z-index: 1;
    outline: var(--zimm-focus-ring);
    outline-offset: var(--zimm-focus-ring-offset-default);
  }
</style>
</head>
<body>
  <h2>BEFORE (current recipe)</h2>
  <div class="row row-before" id="before-row">
    <a href="#" class="swatch" tabindex="0" role="radio" aria-label="Bay Blue" data-idx="0" id="before-0"></a>
    <a href="#" class="swatch" tabindex="-1" role="radio" aria-label="Ivory" data-idx="1" id="before-1"></a>
    <a href="#" class="swatch" tabindex="-1" role="radio" aria-label="Black" data-idx="2" id="before-2"></a>
    <a href="#" class="swatch" tabindex="-1" role="radio" aria-label="Rose Pink" data-idx="3" id="before-3"></a>
  </div>

  <h2>Z-INDEX ONLY, no position (diagnostic)</h2>
  <div class="row row-zonly" id="zonly-row">
    <a href="#" class="swatch" tabindex="0" role="radio" aria-label="Bay Blue" data-idx="0" id="zonly-0"></a>
    <a href="#" class="swatch" tabindex="-1" role="radio" aria-label="Ivory" data-idx="1" id="zonly-1"></a>
    <a href="#" class="swatch" tabindex="-1" role="radio" aria-label="Black" data-idx="2" id="zonly-2"></a>
    <a href="#" class="swatch" tabindex="-1" role="radio" aria-label="Rose Pink" data-idx="3" id="zonly-3"></a>
  </div>

  <h2>AFTER (proposed fix: position:relative + z-index)</h2>
  <div class="row row-after" id="after-row">
    <a href="#" class="swatch" tabindex="0" role="radio" aria-label="Bay Blue" data-idx="0" id="after-0"></a>
    <a href="#" class="swatch" tabindex="-1" role="radio" aria-label="Ivory" data-idx="1" id="after-1"></a>
    <a href="#" class="swatch" tabindex="-1" role="radio" aria-label="Black" data-idx="2" id="after-2"></a>
    <a href="#" class="swatch" tabindex="-1" role="radio" aria-label="Rose Pink" data-idx="3" id="after-3"></a>
  </div>

  <script>
    // Verbatim-logic port of the real component's roving-focus handler
    // (zimmColourSwatchGroup/index.tsx's handleSwatchesKeyDown) — reproduced here only so this
    // scratch page can move focus via a *real keydown event* the same way the real component
    // does, which matters for matching real :focus-visible modality heuristics faithfully.
    function attachRoving(rowId) {
      var row = document.getElementById(rowId);
      row.addEventListener('keydown', function (event) {
        var key = event.key;
        if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].indexOf(key) === -1) return;
        event.preventDefault();
        var items = Array.prototype.slice.call(row.children);
        if (items.length === 0) return;
        var direction = (key === 'ArrowUp' || key === 'ArrowLeft') ? -1 : 1;
        var activeIndex = items.indexOf(document.activeElement);
        var fromIndex = activeIndex === -1 ? 0 : activeIndex;
        var nextIndex = (fromIndex + direction + items.length) % items.length;
        if (items[nextIndex]) items[nextIndex].focus();
      });
    }
    attachRoving('before-row');
    attachRoving('zonly-row');
    attachRoving('after-row');
  </script>
</body>
</html>

