import React from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import theme from 'app/theme';
import { ZimmTokensGlobal } from 'app/theme/zimmTokensGlobal';
import { ZimmColourSwatch } from 'app/components/ui-kits/atoms/zimmColourSwatch';

describe('focus-visible jsdom probe', () => {
  test('does getComputedStyle reflect _focusVisible-conditional styles after .focus()?', () => {
    render(
      <ChakraProvider theme={theme}>
        <MemoryRouter>
          <ZimmTokensGlobal />
          <ZimmColourSwatch name="Bay Blue" imageUrl="https://example.com/x.jpg" isSelected={false} isFocusable={true} />
        </MemoryRouter>
      </ChakraProvider>,
    );
    const swatch = screen.getByRole('radio');
    swatch.focus();
    const cs = getComputedStyle(swatch);
    console.log('matches(:focus-visible)?', swatch.matches(':focus-visible'));
    console.log('position:', cs.position);
    console.log('zIndex:', cs.zIndex);
    console.log('outlineStyle:', cs.outlineStyle);
    console.log('outline:', cs.outline);
  });
});
EOF
